namespace editor {
namespace {
constexpr std::string_view EngineDefinitions = R"(---@meta
-- Generated by SRI Editor. For LuaLS only; never require this file.

Log = {}
---Write an informational message to the editor Log.
---@param message string
function Log.info(message) end
---@param message string
function Log.warning(message) end
---@param message string
function Log.error(message) end

---@class Vector3
---@field x number
---@field y number
---@field z number
Vector3 = {}
---@overload fun(): Vector3
---@param x number
---@param y number
---@param z number
---@return Vector3
function Vector3.new(x, y, z) end

---@class Entity
Entity = {}
---@return boolean
function Entity:IsValid() end
---Returns a copy of the owner's local position. Raises an error for an invalid owner.
---@return Vector3
function Entity:GetPosition() end
---Sets local position; all coordinates must be finite. Requires a valid owner.
---@param position Vector3
function Entity:SetPosition(position) end

---Available only in GameObject script instances, not autoloads or shared modules.
---@type Entity
entity = nil

Scene = {}
---Queues a scene change after gameplay callbacks. Autoloads survive the change.
---@param name string Scene name or project scene path.
---@return boolean success
---@return string error
function Scene.OpenLevel(name) end
)";

bool WriteChanged(const std::filesystem::path& path, std::string_view text, std::string& error) {
    if (std::filesystem::exists(path)) {
        std::string previous;
        if (!engine::ReadTextFile(path, previous, error)) return false;
        if (previous == text) return true;
    }
    return engine::WriteFileAtomic(path, text, error);
}

// LuaLS accepts both dotted keys and nested objects. Preserve either representation.
nlohmann::json* FindSetting(nlohmann::json& config, const std::string& name) {
    if (config.contains(name)) return &config[name];
    const auto dot = name.find('.');
    const auto section = config.find(name.substr(0, dot));
    if (section != config.end() && section->is_object()) {
        const auto value = section->find(name.substr(dot + 1));
        if (value != section->end()) return &*value;
    }
    return nullptr;
}
}

bool refreshLuaDefinitions(const engine::Project& project, std::string& error) {
    if (!engine::ValidateAutoloadDefinitions(project.autoloads, error)) return false;
    try {
        if (project.file.empty() || project.Root().empty()) {
            error = "Lua definitions require a saved project location";
            return false;
        }
        const auto directory = project.Root() / ".sri/lua";
        std::filesystem::create_directories(directory);
        if (!WriteChanged(directory / "engine.d.lua", EngineDefinitions, error)) return false;
        std::string definitions = "---@meta\n-- Generated by SRI Editor. Names only; maintain each autoload's contract in your scripts.\n\n---@class (exact) SRI_Autoloads\n";
        for (const auto& definition : project.autoloads) {
            definitions += "---@field " + definition.name + " table<string, any>";
            if (!definition.enabled) definitions += "? Disabled; absent during Play.";
            definitions += '\n';
        }
        definitions += "\n---@type SRI_Autoloads\nAutoloads = nil\n";
        if (!WriteChanged(directory / "autoloads.d.lua", definitions, error)) return false;

        const auto configPath = project.Root() / ".luarc.json";
        if (!std::filesystem::exists(configPath) && std::filesystem::exists(project.Root() / ".luarc.jsonc")) {
            error = "Definitions updated in .sri/lua. Add '.sri/lua' to workspace.library in your existing .luarc.jsonc";
            return false; // Do not replace the user's commented configuration or shadow it with another file.
        }
        nlohmann::json config = nlohmann::json::object();
        std::string original;
        if (std::filesystem::exists(configPath)) {
            if (!engine::ReadTextFile(configPath, original, error)) return false;
            config = nlohmann::json::parse(original);
        }
        if (!config.is_object()) throw std::runtime_error(".luarc.json must contain a JSON object");
        auto* librarySetting = FindSetting(config, "workspace.library");
        if (!librarySetting) {
            config["workspace.library"] = nlohmann::json::array();
            librarySetting = &config["workspace.library"];
        }
        auto& libraries = *librarySetting;
        if (!libraries.is_array()) throw std::runtime_error(".luarc.json workspace.library must be an array");
        for (const auto& library : libraries)
            if (!library.is_string()) throw std::runtime_error(".luarc.json workspace.library must contain paths");
        if (std::find(libraries.begin(), libraries.end(), ".sri/lua") == libraries.end()) libraries.push_back(".sri/lua");
        if (!FindSetting(config, "runtime.version")) config["runtime.version"] = "Lua 5.4";
        if (!FindSetting(config, "runtime.path")) config["runtime.path"] = {"content/?.lua", "content/?/init.lua"};
        // Preserve the file byte-for-byte when it already contains the required settings.
        if (!original.empty() && nlohmann::json::parse(original) == config) { error.clear(); return true; }
        if (!WriteChanged(configPath, config.dump(2) + '\n', error)) return false;
        error.clear();
        return true;
    } catch (const std::exception& exception) {
        error = "LuaLS setup: " + std::string(exception.what());
        return false;
    }
}
}
